class Solution:
 def largestPerimeter(self,nums):
  nums.sort(reverse=True)
  for i in range(len(nums)-2):
   if nums[i+1]+nums[i+2]>nums[i]:return nums[i]+nums[i+1]+nums[i+2]
  return 0

class Solution:
 def sortedSquares(self,nums):
  n=len(nums);out=[0]*n;l=0;r=n-1
  for i in range(n-1,-1,-1):
   if abs(nums[l])>abs(nums[r]):out[i]=nums[l]*nums[l];l+=1
   else:out[i]=nums[r]*nums[r];r-=1
  return out

class Solution:
 def sumEvenAfterQueries(self,nums,queries):
  total=sum(x for x in nums if x%2==0);out=[]
  for val,i in queries:
   if nums[i]%2==0:total-=nums[i]
   nums[i]+=val
   if nums[i]%2==0:total+=nums[i]
   out.append(total)
  return out

class Solution:
 def addToArrayForm(self,num,k):
  i=len(num)-1;out=[]
  while i>=0 or k:
   if i>=0:k+=num[i];i-=1
   out.append(k%10);k//=10
  return out[::-1]

class Solution:
 def findJudge(self,n,trust):
  score=[0]*(n+1)
  for a,b in trust:score[a]-=1;score[b]+=1
  for i in range(1,n+1):
   if score[i]==n-1:return i
  return -1

from collections import Counter
class Solution:
 def commonChars(self,words):
  common=Counter(words[0])
  for w in words[1:]:common &= Counter(w)
  return list(common.elements())

class Solution:
 def largestSumAfterKNegations(self,nums,k):
  nums.sort(key=abs,reverse=True)
  for i,x in enumerate(nums):
   if x<0 and k>0:nums[i]=-x;k-=1
  if k%2:nums[-1]=-nums[-1]
  return sum(nums)

class Solution:
 def bitwiseComplement(self,n):
  mask=1
  while mask<n:mask=(mask<<1)|1
  return n^mask

class Solution:
 def canThreePartsEqualSum(self,arr):
  total=sum(arr)
  if total%3:return False
  target=total//3;parts=0;cur=0
  for x in arr[:-1]:
   cur+=x
   if cur==target:
    parts+=1;cur=0
    if parts==2:return True
  return False

class Solution:
 def prefixesDivBy5(self,nums):
  rem=0;out=[]
  for b in nums:rem=(rem*2+b)%5;out.append(rem==0)
  return out
